import React, { useState, useEffect } from "react";
import "./UserDashboard.css";

export default function UserDashboard() {
  const [checkIn, setCheckIn] = useState(null);
  const [checkOut, setCheckOut] = useState(null);
  const [timer, setTimer] = useState("00:00:00");
  const [history, setHistory] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const [filter, setFilter] = useState("all");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  useEffect(() => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      window.location.href = "/login";
      return;
    }

    const storedUser = localStorage.getItem("currentUser");
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (e) {
        console.error("Corrupted user data");
      }
    }

    fetch(`http://localhost:5000/api/attendance/${userId}`)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to load attendance");
        return res.json();
      })
      .then((data) => {
        const sorted = data.sort((a, b) => b.date.localeCompare(a.date));
        setHistory(sorted);

        const today = new Date().toISOString().split("T")[0];
        const todayEntry = sorted.find((item) => item.date === today);

        if (todayEntry) {
          if (todayEntry.checkIn) {
            setCheckIn(new Date(`${todayEntry.date} ${todayEntry.checkIn}`));
          }
          if (todayEntry.checkOut) {
            setCheckOut(new Date(`${todayEntry.date} ${todayEntry.checkOut}`));
          }
        }
      })
      .catch((err) => {
        console.error(err);
        setHistory([]);
      })
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    let interval = null;
    if (checkIn && !checkOut) {
      interval = setInterval(() => {
        const diff = Date.now() - checkIn.getTime();
        const hrs = String(Math.floor(diff / 3600000)).padStart(2, "0");
        const mins = String(Math.floor((diff % 3600000) / 60000)).padStart(2, "0");
        const secs = String(Math.floor((diff % 60000) / 1000)).padStart(2, "0");
        setTimer(`${hrs}:${mins}:${secs}`);
      }, 1000);
    } else {
      setTimer("00:00:00");
    }
    return () => clearInterval(interval);
  }, [checkIn, checkOut]);

  const handleCheckIn = () => {
    if (checkIn) return alert("Already checked in today!");

    const now = new Date();
    const time = now.getHours() + now.getMinutes() / 60;
    const graceTime = 9.25; // 9:15 AM

    if (time < graceTime) {
      return alert("Check-in allowed only after 9:15 AM");
    }

    let reason = null;
    if (time > graceTime) {
      reason = prompt("Late check-in after 9:15 AM. Please provide reason:");
      if (!reason || reason.trim() === "") {
        alert("Reason required for late check-in");
        return;
      }
      reason = reason.trim();
    }

    setCheckIn(now);

    const userId = localStorage.getItem("userId");
    const date = now.toISOString().split("T")[0];
    const checkInStr = now.toLocaleTimeString();

    fetch(`http://localhost:5000/api/attendance/${userId}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ date, checkIn: checkInStr, reason }),
    })
      .then((res) => res.json())
      .then((data) => {
        setHistory((prev) => [data, ...prev.filter((h) => h.date !== date)]);
      })
      .catch((err) => console.error(err));
  };

  const handleNormalCheckout = () => {
  if (!checkIn || checkOut) return;

  const now = new Date();
  const currentTime = now.getHours() + now.getMinutes() / 60;

  const isHalfDayWindow = currentTime >= 13 && currentTime <= 14;     // 1:00 PM – 2:00 PM
  const isFullDayWindow = currentTime >= 18.5 && currentTime <= 19;   // 6:30 PM – 7:00 PM

  if (!isHalfDayWindow && !isFullDayWindow) {
    return alert(
      "Normal checkout allowed only:\n• 1:00 PM – 2:00 PM (Half Day)\n• 6:30 PM – 7:00 PM (Full Day)"
    );
  }

  // Calculate actual worked hours
  const workedHours = (now - checkIn) / 3600000;

  // If in Full Day window (6:30–7:00 PM), allow checkout even if <9 hours
  if (isFullDayWindow) {
    performCheckout(now, false); // Normal full day checkout — no reason needed
    return;
  }

  // For Half Day window (1:00–2:00 PM): still require minimum 4 hours
  if (isHalfDayWindow && workedHours < 4) {
    const remaining = 4 - workedHours;
    const hrs = Math.floor(remaining);
    const mins = Math.round((remaining - hrs) * 60);
    return alert(`Minimum 4 hours required for half day.\nRemaining: ${hrs}h ${mins}m`);
  }

  // If somehow outside logic (should not happen), proceed
  performCheckout(now, false);
};

  const handleEarlyCheckout = () => {
    if (!checkIn || checkOut) return;

    const reason = prompt("Requesting Early Checkout\nPlease provide valid reason (e.g., medical, family emergency):");
    if (!reason || reason.trim() === "") {
      return alert("Reason is required for early checkout");
    }

    performCheckout(new Date(), true, reason.trim());
  };

  const performCheckout = (checkoutTime, isEarly = false, earlyReason = null) => {
    setCheckOut(checkoutTime);

    const workedHours = ((checkoutTime - checkIn) / 3600000).toFixed(2);
    const userId = localStorage.getItem("userId");
    const date = checkIn.toISOString().split("T")[0];
    const checkOutStr = checkoutTime.toLocaleTimeString();

    const payload = {
      date,
      checkOut: checkOutStr,
      hours: workedHours,
      isEarlyCheckout: isEarly,
    };

    if (isEarly) {
      payload.checkoutRequestReason = earlyReason;
      payload.requestedAt = checkOutStr;
    }

    fetch(`http://localhost:5000/api/attendance/${userId}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then((res) => res.json())
      .then((data) => {
        setHistory((prev) => [data, ...prev.filter((h) => h.date !== date)]);
        alert(isEarly ? "Early checkout recorded!" : "Normal checkout recorded!");
      })
      .catch((err) => console.error(err));
  };

  const filteredHistory = history.filter((item) => {
    const itemDate = new Date(item.date);
    const today = new Date();

    if (filter === "today") return itemDate.toDateString() === today.toDateString();
    if (filter === "month")
      return itemDate.getMonth() === today.getMonth() && itemDate.getFullYear() === today.getFullYear();
    if (filter === "range" && fromDate && toDate)
      return itemDate >= new Date(fromDate) && itemDate <= new Date(toDate);

    return true;
  });

  return (
    <div className="dashboard">
      <div className="profile-card">
        <img src="https://i.imgur.com/4Z7mK2K.png" alt="employee" />
        {loading ? (
          <p>Loading...</p>
        ) : user ? (
          <>
            <h2>{user.name || "Employee"}</h2>
            <p>{user.designation || "N/A"}</p>
            <p className="id">{user.userId}</p>
          </>
        ) : (
          <p>No user data</p>
        )}

        <button className="logout" onClick={() => { localStorage.clear(); window.location.href = "/login"; }}>
          Logout
        </button>
      </div>

      <div className="attendance-card">
        <h3>Attendance Dashboard</h3>

        <div className="times">
          <div><span>Check In</span><p>{checkIn ? checkIn.toLocaleTimeString() : "--:--"}</p></div>
          <div><span>Check Out</span><p>{checkOut ? checkOut.toLocaleTimeString() : "--:--"}</p></div>
          <div><span>Working Time</span><p>{timer}</p></div>
        </div>

        <div className="buttons">
          <button onClick={handleCheckIn} disabled={!!checkIn}>Check In</button>

          <button onClick={handleNormalCheckout} disabled={!checkIn || !!checkOut}>
            Check Out (Normal)
          </button>

          <button
            onClick={handleEarlyCheckout}
            disabled={!checkIn || !!checkOut}
            className="early-request-btn"
          >
            Request Early Checkout
          </button>
        </div>

        <div className="filters">
          <button onClick={() => setFilter("all")} className={filter === "all" ? "active" : ""}>All</button>
          <button onClick={() => setFilter("today")} className={filter === "today" ? "active" : ""}>Today</button>
          <button onClick={() => setFilter("month")} className={filter === "month" ? "active" : ""}>This Month</button>

          <div className="date-range">
            <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
            <input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} />
            <button onClick={() => setFilter("range")} disabled={!fromDate || !toDate}>Apply Range</button>
          </div>
        </div>

        <table>
          <thead>
            <tr>
              <th>Date</th>
              <th>Check In</th>
              <th>Check Out</th>
              <th>Hours</th>
              <th>Late Reason</th>
              <th>Early Checkout</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredHistory.length === 0 ? (
              <tr><td colSpan="7" style={{ textAlign: "center" }}>No records found</td></tr>
            ) : (
              filteredHistory.map((item, i) => {
                // Determine Present (P) or Absent (A)
                const status = item.checkIn && item.checkOut ? "P" : "A";

                // Hours display
                const hoursDisplay = item.hours
                  ? item.isEarlyCheckout
                    ? `${item.hours} (Early)`
                    : item.hours
                  : "--";

                // Early checkout display with full reason
                const earlyDisplay = item.isEarlyCheckout ? (
                  <span
                    title={item.checkoutRequestReason || "Early checkout"}
                    style={{ color: "#d32f2f", fontWeight: "bold", cursor: "help" }}
                  >
                    Yes ({item.checkOut?.split(" ")[0] || "--"})<br />
                    {item.checkoutRequestReason ? item.checkoutRequestReason : ""}
                  </span>
                ) : "--";

                return (
                  <tr key={i}>
                    <td>{item.date}</td>
                    <td>{item.checkIn || "--:--"}</td>
                    <td>{item.checkOut || "--:--"}</td>
                    <td><strong>{hoursDisplay}</strong></td>
                    <td>{item.reason || "--"}</td>
                    <td>{item.checkoutRequestReason}</td>
                    <td style={{ 
                      fontWeight: "bold", 
                      color: status === "P" ? "green" : "red",
                      fontSize: "18px"
                    }}>
                      {status}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
